starter.css:
.marquee { overflow: hidden; background: #f1eefb; padding: 8px 0; margin-block-end: 16px; }
.marquee__track { white-space: nowrap; animation: scroll-names 12s linear infinite; }
@keyframes scroll-names { from { transform: translateX(100%); } to { transform: translateX(-100%); } }

.cards { display: grid; grid-template-columns: repeat(3, 320px); gap: 16px; }
.card { border: 1px solid #c9c4dc; border-radius: 12px; padding: 12px 16px; }
.card h3 { margin: 0; font-size: 18px; }
.stepper { display: flex; align-items: center; gap: 0; }
.stepper button { width: 16px; height: 16px; padding: 0; font-size: 12px; line-height: 1; border: 1px solid #5b3cc4; background: #fff; }
.stepper span { padding-inline: 8px; }

solution.css:
.marquee { overflow: hidden; background: #f1eefb; padding: 8px 0; margin-block-end: 16px; }
.marquee__track { white-space: nowrap; animation: scroll-names 12s linear infinite; }
.marquee--paused .marquee__track { animation-play-state: paused; }
@keyframes scroll-names { from { transform: translateX(100%); } to { transform: translateX(-100%); } }

@media (prefers-reduced-motion: reduce) {
  .marquee__track { animation: none; }
}

.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); gap: 1rem; }
.card { border: 1px solid #c9c4dc; border-radius: 12px; padding: 12px 16px; }
.card h3 { margin: 0; font-size: 1.125rem; }
.stepper { display: flex; align-items: center; gap: 4px; }
.stepper button { min-inline-size: 2.75rem; min-block-size: 2.75rem; padding: 0; font-size: 1.25rem; line-height: 1; border: 1px solid #5b3cc4; background: #fff; }
.stepper span { padding-inline: 8px; }

solution.js:
const marquee = document.querySelector('.marquee');
const toggle = document.querySelector('.marquee-toggle');

toggle.addEventListener('click', () => {
  const paused = toggle.getAttribute('aria-pressed') === 'true';
  toggle.setAttribute('aria-pressed', String(!paused));
  marquee.classList.toggle('marquee--paused', !paused);
});
